    copticArabicText: `شب هموت ناك بينتشويس بيننوتي إيثبي تينكوينونيا إيبول خين بيكسوما نيم بيكسنوف إيثو إيتيمي. إيمبريتوشوبي نان إيأوأبوكريما ألا إيأوجوم إنتي نينبسيخي نيم نينسوما نيم نينبنيفما.

إنثوك بينتشويس بينهيلبيس نيم بينأوجاي نيم بينأونه نيم بينتونف نيم بينباأووي.

أريه إيرون بينتشويس خين نيكتشيج إيثو إيبول خا نيثليبيس نيبين نيم بيبيثوو.

تينتوبه إمموو إيسشاجي نيم بيسشيري إيفشوبي نان إيأوتشو إيبول إنتي نيننوبي. ثيوتوكوس ماريا تيباثينوس إيثو.

بيأووو إنفنوتي خين نييتهووت.
أووه هيريني هيجين بيكاهي.
نيم أوثيليل خين نيروومي.

بوك خين أوهيريني خين فران إمبشويس. آمين.

بينتشويس ييسوس بيخريستوس بيشيري إمفنوتي إيتونه بيبويثوس إنتي نيتشتوت أووه بياناستاسيس إنتي نيتثمووت — أريثيس إيبيهوي إيتيكهيريني. آمين.

بيميتاغابي إمفنوتي فيوت نيم بيهموت إمبيفشيري إنأووت بينتشويس ييسوس بيخريستوس نيم بيكوينونيا إمبيبنيفما إيثو باراكليتوس ماروشوبي نيم تيرو.

آمين — آمين — آمين.`,
