    copticArabicText: `ماريينجو إمبينيشتي إنهومولوجيا إنتينيستي إناتو.

تينناهتي إاوونوتي إنووت أفنوتي بيووت بانتوكراتور في إتافتي هيسي إيبول خارون نيم بيريتي إنتي بيساجي إنتي أفنوتي.

ووه تينناهتي إاوتشويس إنووت ييسوس بيخريستوس بيشيري إمأفنوتي بيمونوجينيس في إتافشوبي إيبول خين بيووت ها نيييون تيرو.

ووه تينناهتي إبيبنيوما إتهووأب بيتشويس في إفتانخو في إتينيف إيبول خين بيووت.

ووه إاو إيككليسيا إنووت إتهووأب كاثوليكي نيم أبوستوليكي. تيريريومولوجي إاو بابتيسما إنووت إيبول إنهيت إنينوبي. تينأرهيلبيزين إبيتي إناناستاسيس إننيثموووت نيم بيووونخ إنتي بييون إتنيو. آمين.`,
