    copticArabicText: `بيأواب إننيأواب.

أواي بي فيوت إتهووأب — أواي بي بيشيري إتهووأب — أواي بي بيبنيوما إتهووأب. آمين.

إيلوجيمينوس بيتشويس ييسوس بيخريستوس بيشيري إمأفنوتي خين تيفي نيم بيكاهي.
أوسانا خين نييتهووت. آمين.

بينيوت إتخين نيفيووي ماريفتيأووو بيكران. ماريتي بيكميتأوورو. بيتيشاك ماريفشوبي إنثي إيتسهيوت خين تيفي نيم هيجين بيكاهي.

بينييك إنتي راس ماتينفس إيرون إمفوو. ووه خا نيننوبي نان إيبول إنثي إتينخا نيتيريرنوبي إيرون إيبول. ووه إمبريتين إاهون إيبيراسموس ألا ناهمين إيبول خا بيبيثوو.

جي ثوك تي تيميتأوورو نيم تيجوم نيم بيأووو شا إنيه. آمين.

تيناهتي تيناهتي تيناهتي جي فاي بي كيميثميي بيكسوما نيم بيكسنوف بيخريستوس بينأوورو بيننوتي.

آمين — هليلويا.

آجيوس أو ثيوس آجيوس إيسخيروس آجيوس آثاناتوس.

بيميه إنتي تيفي نيم بيكاهي خين بيفأووو إتهووأب.

بانتوكراتور بينتشويس ييسوس بيخريستوس بيشيري إمأفنوتي إيتونه بيهيب إمأفنوتي في إتوله إمبينوبي إمبيكوسموس. إيبيبليبي إيرون خين أوبال إنتي ناي نيم أوشفيري إيبي بيناسثينيا.

شيب بينتشويس إنتينكوينوني إيبول خين بيكسوما نيم بيكسنوف إيتشو إيبول إنتي نينوبي نيم بيوونه إتهاهيراتف. ووه ماريتين شوبي إنسينكوينونوس خين بيكسوما نيم بيكسنوف إتهووأب.

أوبين إمبريإيرشوبي نان إيأوأبوكريما ألا إيأواسموس إنتي بيسوما نيم تيبسيخي نيم بيبنيوما.

آجيوس فيوت — آجيوس بيشيري — آجيوس بيبنيوما إتهووأب.

بيسوما إتهووأب إتيمي.
بيسنوف إتهووأب إتيمي.

بيسوما نيم بيسنوف إتهووأب إتيمي إمبيشيري إمأفنوتي سيتاأف ناي إمبينيشتي إنخو إيبول نيم بيوونه إتهاهيراتف. آمين.`,
