    id: "basil-post-communion",
    title: "صلاة شكر بعد التناول",
    role: "الكاهن",
    text: `صلاة شكر بعد التناول

ًيقول الكاهن هذه الأوشية شكرا هلل من بعد

تناول الأسرار المقدسة، وهي للآب:

الكاهن:

فمنا امتأل فرحاً ولساننا تهليلاً من

أجل تناولنا من أسرارك غير

المائتة يا رب.

لأن ما لم تره عين ولم تسمع به

أذن ولم يخطر على قلب بشر.

ما أعددته يا الله لمحبي إسمك

القدوس، هذا أعلنته لألطفال

الصغار الذين لكنيستك المقدسة.

نعم أيها الآب، إن هذه هي

المسرة التي كانت أمامك، لأنك

رحيم.

ونرسل لك إلى فوق المجد

والإكرام، أيها الآب والإبن

والروح القدس.

الآن وكل أوان وإلى دهر الدهور

كلها. آمين.

وبعد التناول في يوم خميس العهد، تستبدل

الفقرة الأولي من صلاة الشكر المذكورة

أعاله بما يلي:

الكاهن:

نشكرك أيها الرب محب البشر،

صانع الخيرات لنفوسنا، يا من

جعلتنا مستحقين في مثل هذا

اليوم ألسرارك السمائية والغير

المائتة.

لأن ما لم تره عين ولم تسمع به

أذن ولم يخطر على قلب بشر...`,
