    id: "fraction-isaac-sacrifice",
    title: "قسمة ذبح إسحق (للآب)",
    role: "الكاهن",
    text: `وأيضًا قسمةٌ للآب، والبعضُ يقولُها في الخميس الكبير

وحدَثَ في الأيامِ الَّتي أرادَ اللهُ أن يُجرِّبَ إبراهيمَ ويعلَمَ قلبَهُ ومحبَّتَهُ فيهِ. إنَّهُ قالَ لهُ إبراهيمُ، خُذ ابنَكَ الحبيبَ إسحقَ وقدِّمهُ لي مُحرَقةً على الجبلِ الَّذي أُعلِمُكَ بهِ. فقامَ إبراهيمُ باكِرًا وأسرَجَ دابَّتَهُ، وأخذَ غُلامَينِ وإسحقَ ابنَهُ، وأخذَ سِكِّينًا ونارًا، ومشَى على الأرض، فرأى الموضعَ مِنْ بعيدٍ الَّذي أعلَمَهُ بهِ الرَّبُّ. فقالَ لهُ لغُلامَيهِ اجلِسَا أنتُما هُنا مع الدابةِ، وأمَّا أنا وإسحقُ ابني فنذهَبُ ونسجُدُ ثم نرجِعُ إليكُما.

وأخَذَ إبراهيمُ حِجارةً وبنَى مَذبَحًا، وأخَذَ الحطَبَ ورفعَهُ على المذبح، وأخَذَ إسحقَ ابنَهُ وربَطَهُ ووضعَهُ على المذبح، وأخَذَ السكينَ ليذبَحَهُ. فقالَ إسحقُ لأبيهِ، يا أبتاهُ هوذا النارُ والحطَبُ، وأينَ الخروفُ الَّذي نُقدِّمُهُ للمُحرَقةِ، فقالَ لهُ إبراهيمُ إنَّ اللهَ الَّذي أمَرَنا أن نرفعَ لهُ ذبيحةً هو يَرى حَمَلاً للمُحرَقةِ يا ابني.

وإنَّ مَلاكَ الرَّبِّ نادَى إبراهيمَ قائلاً لهُ، إبراهيمُ إبراهيمُ، انظُرْ لا تَلمِسْ فتاكَ ولا تصنَعَ بهِ شَرًّا. لمَّا نظَرَ الرَّبُّ محبَّتَكَ فيهِ، فقالَ إنِّي أنا هو الرَّبُّ إلهُكَ أقسَمتُ بذاتي إنَّكَ بالبَرَكةِ أُبارِكُكَ، وبالكَثرةِ أُكثِّرُ نسلَكَ. فرفَعَ إبراهيمُ عينَيهِ فنظَرَ خروفًا عِندَ الشجَرةِ مُوثَّقًا بقَرنَيهِ، فتَرَكَ إسحقَ ابنَهُ وأخَذَ الخروفَ وأصعَدَهُ مُحرَقةً عِوضًا عنهُ.

فذَبْحُ إسحقَ كانَ إشارةً إلى هَرَقِ دمِ المَسيحِ ابنِ اللهِ على الصَّليبِ عن خلاصِ العالم. وكما حَمَلَ إسحقُ حطَبَ المُحرَقةِ، كذلكَ حَمَلَ المَسيحُ خشبةَ الصَّليبِ. وكما رَجَعَ إسحقُ حيًّا، هكذا أيضًا المَسيحُ قامَ حيًّا مِنَ الأمواتِ وظهَرَ لتلاميذِهِ هؤلاءِ القدِّيسين.

اللهُمَّ الَّذي قَبِلَ ذَبيحةَ أبينا إبراهيم، اقبَلْ هذهِ الذَّبيحةَ مِنَّا في هذهِ السَّاعة، بارِكْ هذهِ القرابينَ، بارِكْ الَّذينَ قُدِّمَت عنهُم، نيِّحْ نُفوسَ الأمواتِ، فليُبارِكُ المَسيحُ على قلوبِنا جميعًا وأرواحِنا.

لكَيْ بقلبٍ طاهرٍ، ونفسٍ مستنيرةٍ، ووجهٍ غيرِ مخزيٍّ، وإيمانٍ بلا رياءٍ، ومحبَّةٍ كاملةٍ، ورجاءٍ ثابتٍ. نجسُرَ بدالةٍ بغيرِ خوفٍ، يا اللهُ الآبُ القُدُّوسُ الَّذي في السَّمَواتِ ونقولَ.

أبَانَا...`,
