    copticArabicText: `أشوبي دي هين نيإيهو إيتا أفنوتي أووش إيبوت إنأبراهام · أووه إنتيفإيمي إيبيفهيت نيم بيفميهي إيبورن إيروف. أووه بيخاف ناف خي أبراهام أبراهام · خي إمبيكمينريت إنشيري إيساأك أووه أنيتف ني نو بلا · هيخين بيتوو إيتناتامووك إيروف. أفتونف دي إنخي أبراهام إنتوري · أووه أفهوك إنتيفإيشو · أفخي دي إنألوت سناو نيم إيساأك بيفشيري · أفخي نوخورت نيم أوخروم · أفموشي إيبول هيخين بيكاهي · أووه أفناو إيبيما هي فو أوي إيتا إيبشويس تاموف إيروف.

أووه بيخاف إنيفألوري خي هيمسي إنوتين إمبايما نيم تيشو · أنووك دي نيم إيساأك باشيري تينناشينان إنتينو أووشت أووه إنتينتاسثو هاروتين. أفخي دي إنخي أبراهام إننيروكس إنتي بيبلا · أووه أفتالو أوخين إيساأك بيفشيري · أفخي دي إمبيخروم هين تيفجيج نيم تيخورت.

بيخيإيساأك دي إمبيفيوت · خي بايوت هإمبي إيس بيخروم نيم بيروكس · أفثون بيإيسو إيتيننايينف إيبيبلا · بيخيأبراهام دي ناف خي أفنوتي فييتافأوراهساخني نان إيتالو ناف نووو أوسيا · إنثوف إيثنانو إيبول إيأووإيسو ناف إيبيبلا باشيري. أفخي دي إنهانلوني إنخي أبراهام أفكوت نوومانيرشورش · أفخي إننيروكس أفتالو هيخين بيمانيرشورش · أووه أفخي إنإيساأك بيفشيري أفسوأونف أفتالوف إيهريهي إيخين بيمانيرشورش · أفخي إنتيخورت إيبيلثولف.

أووه أ بيأغيلوس إنتي إيبشويس مو أوي إيت أوبي أبراهام إيفخو إممووس ناف · خي أبراهام أبراهام أنات · إمبيرووس إيبيكألور أودي إمبيريري ناف نوبيتشو. إيتافناو إنخي إيبشويس إيبيكميهي إيبورن إيروف · أووه بيخاف خي أنووك بي إيبشويس بيكنوتي · أيورك إمموي خي هين أو سمو إيإيسمو إيروك · أووه هين أو أشاي إيإيثري بيكخروه أشاي.

أفتونف إنخي أبراهام إننيبال · أفناو إيأووإيسو إيفخي إيخين بيشوني إيفميهر هين بيفتاب سناو · أووه أفخو إنإيساأك بيفشيري أفخي إمبيإيسو · أووه أفإينف إيهريهي نوبلا إنتيفميبيو.

بيدولديل دي إنإيساأك ني أووبوريم بي إيبيفون إيبول إمبيسنوف إمبيخريستوس بيشيري إمأفنوتي هيخين بيستاوروس إيثبي بيأوخاي إمبيكوسموس. أووه كاتا فريت إيتا إيساأك أولي إننيروكس إنتي بيبلا · بايريت أفأولي إنخي بيخريستوس إمبيشي إنتي بيستاوروس. أووه كاتا فريت إيتا إيساأك تاسثو إيفأونه · بايريت هوف بيخريستوس أفتونف إيفأونه إيبول هين نييثموت أووه أفأووونهف إنيفأخيوس إممثيتيس.

أفنوتي فييتافخي إنتوسيا إنتي بينيوت أبراهام · خي إنتايوسيا إنتوتين هين تايأونو ثاي · سمو إيناي دورون ناي · سمو إينييتاريننو إيخو · ماهتون إننيبسيخي إننييتاتمو · ماريفسمو إنخي بيخريستوس إيخين نينهيت تيرو نيم نينبنيفما.

خي هينا هين أو هيت إيفأواب · نيم أو نيبسيخي إياسبيأووويني · نيم أو هو ناتبيشوبي · نيم أو ناهت ناتميتشوبي · نيم أو أغابي إيسهيك إيبول · نيم أو هيلبيس إيستاخريهوت.

إنتينيرتولمان هين أو باريسيا ناتيرهوت إيتوبز إممووك · أفنوتي فيوت إيثو إيت هين نيفيري · أووه إيخوس. جي بينيوت...`,
