    id: "misc-reconciliation-father-2",
    title: "صلاة صلح أخرى للآب (صلوات متنوعة ٤)",
    role: "الكاهن",
    text: `صلاةُ صلحٍ أُخرى للآب

يا اللهُ سَيِّدَ الكُلِّ، اجعلْنا مُستَحقِّينَ لهذا الخلاصِ، نحنُ غيرَ المُستَحقِّينَ يا مُحبَّ البشرِ.

وطهِّرنا مِنْ كُلِّ دنسٍ، ومِنْ كُلِّ غشٍّ، ومِنْ كُلِّ رياءٍ، ومِنْ كُلِّ فعلٍ خبيثٍ، ومِنْ تِذكارِ الشَّرِّ اللابسِ الموتَ.

واجعلنا مُستحقِّينَ كُلَّنا يا سَيِّدَنا أن نُقبِّلَ بعضُنا بعضًا بقُبلَةٍ مُقدَّسةٍ.

لِكَيْ نكونَ جسدًا واحدًا وروحًا واحدًا برباطِ المحبَّةِ وسلامِ ربِّنَا يَسوعَ المَسيحِ.

[يقول الشَّمَّاسُ: صلُّوا مِنْ أجلِ السَّلامِ الكاملِ...]
[يقول الشَّعبُ: يارَبُّ ارحَم.]

[يقول الكاهِنُ:]
هذا الَّذي أنتَ مُبارَكٌ معهُ، مع الرُّوحِ القُدُسِ المُحيي المُساوي لكَ.

الآنَ وكُلَّ أوانٍ وإلى دَهرِ الدَّاهِرينَ كُلِّها، آمينْ.`,
    copticText: `Ⲫϯ ⲟⲩⲟϩ ⲫⲛⲏⲃ ⲛ̀ⲧⲉ ⲟⲩⲟⲛ ⲛⲓⲃⲉⲛ ⲁⲣⲓⲧⲉⲛ ⲛ̀ⲉⲙⲡϣⲁ ⲙ̀ⲡⲁⲓⲟⲩⲭⲁⲓ ⲫⲁⲓ ⲁⲛⲟⲛ ϧⲁ ⲛⲓⲁⲧⲙ̀ⲡϣⲁ ⲡⲓⲙⲁⲓⲣⲱⲙⲓ.

Ⲟⲩⲟϩ ⲙⲁⲧⲟⲩⲃⲟⲛ ⲉⲃⲟⲗϩⲁ ⲑⲱⲗⲉⲃ ⲛⲓⲃⲉⲛ ⲛⲉⲙ ⲭⲣⲟϥ ⲛⲓⲃⲉⲛ ⲛⲉⲙ ⲙⲉⲧϣⲟⲃⲓ ⲛⲓⲃⲉⲛ ⲛⲉⲙ ⲡⲁⲛⲟⲩⲣⲅⲓⲁ ⲛⲓⲃⲉⲛ ⲛⲉⲙ ϯⲙⲉⲧⲣⲉϥⲉⲣⲫⲙⲉⲩⲓ ⲛ̀ⲧⲉ ϯⲕⲁⲕⲓⲁ ⲉⲧⲉⲣⲫⲟⲣⲓⲛ ⲙ̀ⲫⲙⲟⲩ.

Ⲟⲩⲟϩ ⲁⲣⲓⲧⲉⲛ ⲛ̀ⲉⲙⲡϣⲁ ⲧⲏⲣⲉⲛ ⲡⲉⲛⲛⲏⲃ ⲉⲑⲣⲉⲛⲉⲣⲁⲥⲡⲁⲍⲉⲥⲑⲉ ⲛ̀ⲛⲉⲛⲉⲣⲏⲟⲩ ϩⲉⲛ ⲟⲩⲫⲓ ⲉⲥⲟⲩⲁⲃ.

Ϩⲓⲛⲁ ⲛ̀ⲧⲉⲛϣⲱⲡⲓ ⲛ̀ⲟⲩⲥⲱⲙⲁ ⲛ̀ⲟⲩⲱⲧ ⲛⲉⲙ ⲟⲩⲡⲛⲉⲩⲙⲁ ⲛ̀ⲟⲩⲱⲧ ϩⲉⲛ ⲡⲓⲙⲟⲩⲣ ⲛ̀ⲧⲉ ϯⲁⲅⲁⲡⲏ ⲛⲉⲙ ϯϩⲓⲣⲏⲛⲏ ⲛ̀ⲧⲉ Ⲡⲉⲛⲟ̄ⲥ̄ Ⲓⲏⲥⲟⲩⲥ Ⲡⲓⲭⲣⲓⲥⲧⲟⲥ.

[Ⲡⲣⲟⲥⲉⲩⲝⲁⲥⲑⲉ ⲩⲡⲉⲣ ⲧⲏⲥ ⲧⲉⲗⲓⲁⲥ ⲓⲣⲏⲛⲏⲥ...]
[Ⲕⲩⲣⲓⲉ ⲉⲗⲉⲏⲥⲟⲛ.]

Ⲫⲁⲓ ⲉⲧⲉⲕⲥⲙⲁⲣⲱⲟⲩⲧ ⲛⲉⲙⲁϥ ⲛⲉⲙ Ⲡⲓⲡⲛⲉⲩⲙⲁ ⲉⲑⲟⲩⲁⲃ ⲛ̀ⲣⲉϥⲧⲁⲛϩⲟ ⲟⲩⲟϩ ⲛ̀ⲟⲙⲟⲟⲩⲥⲓⲟⲥ ⲛⲉⲙⲁⲕ.

Ⲧⲛⲟⲩ ⲛⲉⲙ ⲛ̀ⲥⲟⲛ ⲛⲓⲃⲉⲛ ⲛⲉⲙ ϣⲁ ⲉⲛⲉⲍ ⲛ̀ⲧⲉ ⲛⲓⲉⲛⲉⲍ ⲧⲏⲣⲟⲩ ⲁⲙⲏⲛ.`,
    copticArabicText: `أفنوتي أووه فنيب إنتي أووأون نيبين أريتين إنإيمبشا إمبايأوخاي فاي أنون ها نيأتإمبشا بيمايروومي.

أووه ماتوبون إيبول ها ثوليب نيبين نيم خروف نيبين نيم ميتشوبي نيبين نيم بانوورجيا نيبين نيم تيميتريفإيرفميأووي إنتي تيكاكيا إيتيرفوريين إمفمو.

أووه أريتين إنإيمبشا تيرين بيننيب إيثرينيرأسبازيسثي إننيننيريهو هين أووفي إيسأواب.

هينا إنتينشوبي إنأو سوما إنأووت نيم أو بنيفما إنأووت هين بيموور إنتي تيأغابي نيم تيهيريني إنتي بينو أووس ييسوس بيخريستوس.

[بروسيفكساسثي إيبير تيس تيلياس إيريني...]
[كيريي إيليإيسون.]

فاي إيتيكسماروت نيماف نيم بيبنيفما إيثو إنريفتانهو أووه إنأوموأووسيوس نيماك.

تنو نيم إنسون نيبين نيم شا إينيز إنتي نيإيني إنتيز تيرو أمين.`,
