    copticArabicText: `إييبي فيخي نيمان هيخين تايتراب يزا إمفوو إنخي إمانوييل بيننوتي بيشيب إنتي أفنوتي فيتولي إمفنوبي إمبيكوسموس تيرف.

فيتيسيمسي هيخين بيثرونوس إنتي بيفأووو. فيتوروجي إيراتو ناهراف إنخي نيتاغما تيرو إنإيبوراني أون. فيتأوسوس إيروف إنخي نياجيلوس هين نيسمي إنتي بيسموو أووه إيتريتو إيرأوروشت إمموف إنخي نيأرخيأجيلوس. بيفتو إنزوون ناسوماتوس سيخو إمبيسيمنوس إنتي بيتريساجيوس.

أووه بيخوروس إيتور إمبريسبيتيروس سيهيمسي هيخين نوثرونوس إيري خورت إيتور إنخلوم إننوب هيخين نوأفيأوي إيري خورت إيتور إمفراليه إننوب هين نوجيج إيرميس إنسثوينوفي إيتي نيبروسيأوخي إنتي نيأجيوس أووه سيأوروشت إمبيأوثو إمفيتونه شا إينيه إنتي بيينيه.

أووه بيشي إيمي إيتور إنمووو نيبارثينوس ناتوليب سيسوس إيبإبشويس إيرخو إمموس خي أجيوس أجيوس أجيوس آمين أليلويا.

أنون دي هون تينأوروشت إنتيرياس إيثري تينسوس إيروس إينخو إمموس. خي فأواب إنخي أفنوتي فيوت بيبانتوكراتور آمين أليلويا. خوأواب إنخي بيفمونوجينيس إنشيري ييسوس بيخريستوس بيننيب آمين أليلويا. خوأواب إنخي بيبنيفما إيثري إمباراكليتون آمين أليلويا.

سوأواب أووه إيميس إنأووو إنخي تثيوتوكوس إيثو تاجيا مارييا تيباثينوس آمين أليلويا. سوأواب أووه إيميس إنأووو إنخي تايأوسيا ثيتارشات هابوبنه إمبيكوسموس تيرف آمين أليلويا.

إيثبي فاي آ بينسوتير ناغاثوس شوي إيبول إيفخو إمموس خي باسوما أوهري إمميي تي أووه باسنوف أوسو إمميي بي. فيتيثوروم إمباسوما أووه إيتسو إمباسنوف إيفيشوبي إنهيت أووه أنوك هو إيييشوبي إنهيتف.

جينتسو إيروك بيننيب ماتوبو إننينبسيخي نيم نينسوما نيم نينبنيفما. خي هينا هين أوهيت إيفأواب نيم هانسفوتو إيتتوبيأووت نيم أوبسيخي إياسبيأوويني نيم أوهو ناتبيشوبي نيم أوناهت ناتميتشوبي نيم أوسيندييسيس إيستوبيأووت نيم أوهيبوموني إيسهيك إيبول نيم أوهيلبيس إيستاخريأووت.

إنتينيرتولمان هين أوباريسيا ناتيرهوت إيتوبز إمموك أفنوتي فيوت إيثو إيتي هين نيفيري أووه إيخوس. خي بينيوت...`,
